 50	            now(), now() + make_interval(mins => ${HOLD_MINUTES}::int)
 51	        )
 52	        ON CONFLICT ("flightId", "seatNumber") DO UPDATE
 53	            SET "holderKey" = EXCLUDED."holderKey",
 54	                "createdAt" = now(),
 55	                "expiresAt" = now() + make_interval(mins => ${HOLD_MINUTES}::int)
